/// <summary>
/// The <c>AVABPInfoContract</c> class is the controller class for <c>BP-Info</c>
/// </summary>
class AVABPInfoController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVABPInfoService));
    this.parmMethodName(methodStr(AVABPInfoService, runService));
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVABPInfoController</c> as return value
/// </returns>
public static AVABPInfoController newFromArgs(Args _args)
{
    AVABPInfoController controller;

    controller = new AVABPInfoController();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPInfoController     controller;
    AVABPInfoContract       dataContract;
    SysOperationStartResult sysOperationStartResult;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVABPInfoController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();

    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;

            dataContract.parmArgs(_args);
            dataContract.parmKCS_KBVBuildingProjectID(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        }

    }
    else
    {
        dataContract.parmFromKCS_KBVBuildingProjectID(KCS_KBVParameters::find().NDX_KBVBuildingProjectIDFrom);
        dataContract.parmHCMWorker(0);
    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
